package zw.co.hyperfeeds.commerce;
import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequestMapping("/payments/paynow")class PaynowCallbackController{private final JdbcClient jdbc;private final PaymentGateway gateway;private final PaymentStateService states;PaynowCallbackController(JdbcClient j,PaymentGateway g,PaymentStateService s){jdbc=j;gateway=g;states=s;}@PostMapping("/callback")String callback(@RequestParam Map<String,String> form){String reference=form.get("reference");if(reference==null)return"OK";jdbc.sql("select p.id,p.poll_url from payments p join orders o on o.id=p.order_id where o.reference=:r and p.status='SENT_TO_SUBSCRIBER'").param("r",reference).query().listOfRows().stream().findFirst().ifPresent(p->{var verified=gateway.poll((String)p.get("poll_url"));states.complete((UUID)p.get("id"),verified.paid(),verified.status(),verified.paynowReference(),null);});return"OK";}}
